async def act(page):
    """
    From the current 'Create Product Settings' screen, continue to the product edit form,
    create a simple product named 'Lelelumon Yoga Mat' priced at 769.99, with
    size 'uni-size', color 'black', quantity 42, and set it In Stock. Save the product as
    the final action.
    """
    import asyncio

    # No knowledge_base functions are provided in the environment, so none are used.

    # Helper to attempt a sequence of attempts for closing popups or clicking elements
    async def try_click(locator_getter, name_desc=None, timeout=1000):
        try:
            locator = locator_getter()
            await locator.click(timeout=timeout)
            return True
        except Exception:
            return False

    # If a blocking popup exists, try to close it by common accessible button labels.
    # Try several common names for the close control. Don't fail if none present.
    for close_name in ("Close", "close", "Dismiss", "×", "× Close", "Close (Esc)"):
        clicked = await try_click(lambda: page.get_by_role("button", name=close_name), name_desc=f"close {close_name}")
        if clicked:
            # give UI a moment to settle after popup is closed
            await asyncio.sleep(0.3)
            break

    # Click the 'Continue' button under the appropriate row to proceed to the product form.
    # Use the explicit row -> button path to avoid ambiguous top-level button matches.
    try:
        await page.get_by_role("row", name="Continue").get_by_role("button", name="Continue").click()
        await page.wait_for_load_state("networkidle")
        await asyncio.sleep(0.5)
    except Exception:
        # If the structured path fails, attempt direct button fallback (best-effort).
        try:
            await page.get_by_role("button", name="Continue").click()
            await page.wait_for_load_state("networkidle")
            await asyncio.sleep(0.5)
        except Exception:
            # If Continue couldn't be clicked, still proceed to attempt filling fields in case form is already visible.
            await asyncio.sleep(0.5)

    # Fill the product Name
    try:
        await page.get_by_role("textbox", name="Name").fill("Lelelumon Yoga Mat")
    except Exception:
        # fallback: first textbox
        try:
            await page.get_by_role("textbox").nth(0).fill("Lelelumon Yoga Mat")
        except Exception:
            pass

    # Fill the Price
    try:
        await page.get_by_role("textbox", name="Price").fill("769.99")
    except Exception:
        for alt in ("Product Price", "Price ($)", "Price GBP", "price"):
            try:
                await page.get_by_role("textbox", name=alt).fill("769.99")
                break
            except Exception:
                continue

    # Set Size attribute (combobox). Use select_option on the combobox role.
    try:
        await page.get_by_role("combobox", name="Size").select_option(label="uni-size")
    except Exception:
        # try common label variants
        for opt in ("Uni-size", "uni size", "uni-size", "UNI-SIZE"):
            try:
                await page.get_by_role("combobox", name="Size").select_option(label=opt)
                break
            except Exception:
                continue

    # Set Color attribute (combobox)
    try:
        await page.get_by_role("combobox", name="Color").select_option(label="black")
    except Exception:
        for name_variant in ("Colour", "color", "Color"):
            try:
                await page.get_by_role("combobox", name=name_variant).select_option(label="black")
                break
            except Exception:
                continue

    # Open Inventory tab/section to set quantity and stock. Use tab role path if available.
    try:
        await page.get_by_role("tab", name="Inventory").click()
        await asyncio.sleep(0.4)
    except Exception:
        # fallback to button or link
        for role_name in ("button", "link"):
            try:
                await page.get_by_role(role_name, name="Inventory").click()
                await asyncio.sleep(0.4)
                break
            except Exception:
                continue

    # Fill Qty (try common textbox names)
    qty_set = False
    for qty_name in ("Qty", "Quantity", "Qty."):
        try:
            await page.get_by_role("textbox", name=qty_name).fill("42")
            qty_set = True
            break
        except Exception:
            continue
    if not qty_set:
        # fallback to a likely textbox index (best-effort)
        try:
            await page.get_by_role("textbox").filter(has_text="Qty").fill("42")
            qty_set = True
        except Exception:
            try:
                await page.get_by_role("textbox").nth(2).fill("42")
                qty_set = True
            except Exception:
                pass

    # Set Stock Availability to In Stock
    try:
        await page.get_by_role("combobox", name="Stock Availability").select_option(label="In Stock")
    except Exception:
        for alt in ("Stock", "Stock Status", "Availability"):
            try:
                await page.get_by_role("combobox", name=alt).select_option(label="In Stock")
                break
            except Exception:
                continue

    # Final action: Save the product. Use a parent group to avoid ambiguous matches and make this the last action.
    save_clicked = False
    parent_candidates = [
        page.get_by_role("group", name="Page Actions"),
        page.get_by_role("group", name="Actions"),
        page.get_by_role("toolbar"),
        page.get_by_role("banner"),
    ]
    for parent in parent_candidates:
        try:
            await parent.wait_for(timeout=1500)
            await parent.get_by_role("button", name="Save").click()
            save_clicked = True
            break
        except Exception:
            continue

    if not save_clicked:
        try:
            await page.get_by_role("button", name="Save").click()
            save_clicked = True
        except Exception:
            # give UI a brief pause; nothing more reliable we can do here
            await asyncio.sleep(1)

    # Let the save/navigation complete (this is the last action)
    try:
        await page.wait_for_load_state('networkidle')
    except Exception:
        await asyncio.sleep(1)
